            Spacer(Modifier.height(8.dp))

            Text(
                text = "Please setting your language before start using this application",
                style = MaterialTheme.typography.titleMedium,
                textAlign = TextAlign.Center,
                modifier = Modifier
                    .padding(horizontal = 24.dp),
                color = PaleBlack
            )

            Spacer(Modifier.height(32.dp))

            LazyVerticalGrid(
                columns = GridCells.Fixed(2),
                verticalArrangement = Arrangement.spacedBy(12.dp),
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                modifier = Modifier
                    //.weight(1f)                 // <- ini biar FAB tidak terdorong
                    .fillMaxWidth(),
                contentPadding = PaddingValues(bottom = 10.dp)  // ruang scroll
            ) {

                items(languageItems) { lang ->
                    val selected = lang.code == state.languagePreference

                    Card(
                        shape = MaterialTheme.shapes.medium,
                        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp),
                        border = BorderStroke(1.dp, if (selected) PalePink else MediumGray.copy(alpha = 0.4f)),
                        colors = CardDefaults.cardColors(
                            containerColor = if (selected) PalePink.copy(alpha = 0.12f) else Color.White
                        ),
                        modifier = Modifier
                            .height(55.dp)
                            .fillMaxWidth()
                            .clickable(indication = null, interactionSource = remember { MutableInteractionSource() }) {
                                 viewModel.update { it.copy(languagePreference = lang.code) }
                             }
                            .focusable(false)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(horizontal = 16.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = lang.label,
                                style = MaterialTheme.typography.labelSmall,
                                fontWeight = FontWeight.Medium,
                                color = PaleBlack
                            )

                            RadioButton(
                                selected = selected,
                                onClick = {
                                    viewModel.update { it.copy(languagePreference = lang.code) }
                                },
                                colors = RadioButtonDefaults.colors(
                                    selectedColor = PalePink,
                                    unselectedColor = MediumGray,
                                    disabledColor = MediumGray.copy(alpha = 0.4f)
                                )
                            )
                        }
                    }
                }
            }
        }
        FloatingActionButton(
            onClick = {
                // save to firestore
                val uid = AuthHelper.getCurrentUser()?.uid
                if (uid != null) viewModel.saveAll(uid)

                // navigate to AboutScreen when Continue is pressed
                navController.navigate(Routes.ABOUT) {
                    popUpTo(Routes.LANGUAGE) { inclusive = true }
                    launchSingleTop = true
                }

            },
            containerColor = PaleBlack,
            contentColor = PalePink,
            shape = androidx.compose.foundation.shape.CircleShape,
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .padding(bottom = 100.dp)
                .size(48.dp)
        ) {
            Icon(
                imageVector = Icons.AutoMirrored.Filled.ArrowForward,
                contentDescription = "Continue",
                modifier = Modifier.size(28.dp)
            )
        }
    }
}


