@Composable fun RegisterScreen(navController: NavHostController, viewModel: AuthViewModel = viewModel()) { val scrollState = rememberScrollState() val state = viewModel.registerState val snackbarHostState = remember { SnackbarHostState() }
LaunchedEffect(state) { if (state is RegisterState.Error) { snackbarHostState.showSnackbar(state.message) viewModel.registerState = RegisterState.Idle } }
Box( modifier = Modifier .fillMaxSize() .padding(20.dp, 50.dp) ) { Column( modifier = Modifier .verticalScroll(scrollState) .fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(10.dp), horizontalAlignment = Alignment.CenterHorizontally ) { Image( painter = painterResource(id = R.drawable.hyperaid), contentDescription = "Hyperaid logo", modifier = Modifier.widthIn(max = 175.dp) )
Text( text = "Register to your account and manage your health right away!", modifier = Modifier.padding(20.dp, 10.dp), style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.Normal, textAlign = TextAlign.Center )
RegisterField(navController, viewModel, snackbarHostState) OrDivider() LoginOAuth(navController, viewModel)
Spacer(modifier = Modifier.height(25.dp))
Row( verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(5.dp) ) { Label("Have an account?") Text( text = "Login", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodySmall, modifier = Modifier.clickable { navController.navigate("Login") { popUpTo("Register") { inclusive = true } launchSingleTop = true } } ) } }
if (state is RegisterState.Loading) { LoadingFullscreen() }
SnackbarHost( hostState = snackbarHostState, modifier = Modifier.align(Alignment.BottomCenter) ) } }
@Composable fun RegisterField(navController: NavController, viewModel: AuthViewModel, snackbarHostState: SnackbarHostState) { var fullName by remember { mutableStateOf("") } var email by remember { mutableStateOf("") } var password by remember { mutableStateOf("") } var confirmPassword by remember { mutableStateOf("") }
// palette — match LoginScreen val PaleBlack = Color(0xFF2B2B2B) val PalePink = Color(0xFFF6C9CB) val MediumGray = Color(0xFF959595)
Column( modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(10.dp) ) { OutlinedTextField( value = fullName, onValueChange = { fullName = it }, label = { Label("Full Name") }, shape = RoundedCornerShape(25f), textStyle = MaterialTheme.typography.bodySmall, modifier = Modifier.fillMaxWidth(), colors = OutlinedTextFieldDefaults.colors( focusedTextColor = PaleBlack, unfocusedTextColor = PaleBlack, focusedBorderColor = PalePink, unfocusedBorderColor = MediumGray.copy(alpha = 0.6f), focusedLabelColor = PalePink, unfocusedLabelColor = MediumGray, cursorColor = PaleBlack, focusedPlaceholderColor = MediumGray, unfocusedPlaceholderColor = MediumGray ) )
OutlinedTextField( value = email, onValueChange = { email = it }, label = { Label("Email") }, shape = RoundedCornerShape(25f), textStyle = MaterialTheme.typography.bodySmall, modifier = Modifier.fillMaxWidth(), colors = OutlinedTextFieldDefaults.colors( focusedTextColor = PaleBlack, unfocusedTextColor = PaleBlack, focusedBorderColor = PalePink, unfocusedBorderColor = MediumGray.copy(alpha = 0.6f), focusedLabelColor = PalePink, unfocusedLabelColor = MediumGray, cursorColor = PaleBlack, focusedPlaceholderColor = MediumGray, unfocusedPlaceholderColor = MediumGray ) )
OutlinedTextField( value = password, onValueChange = { password = it }, label = { Label("Password") }, visualTransformation = PasswordVisualTransformation(), shape = RoundedCornerShape(25f), textStyle = MaterialTheme.typography.bodySmall, modifier = Modifier.fillMaxWidth(), colors = OutlinedTextFieldDefaults.colors( focusedTextColor = PaleBlack, unfocusedTextColor = PaleBlack, focusedBorderColor = PalePink, unfocusedBorderColor = MediumGray.copy(alpha = 0.6f), focusedLabelColor = PalePink, unfocusedLabelColor = MediumGray, cursorColor = PaleBlack, focusedPlaceholderColor = MediumGray, unfocusedPlaceholderColor = MediumGray ) )
OutlinedTextField( value = confirmPassword, onValueChange = { confirmPassword = it }, label = { Label("Confirm Password") }, visualTransformation = PasswordVisualTransformation(), shape = RoundedCornerShape(25f), textStyle = MaterialTheme.typography.bodySmall, modifier = Modifier.fillMaxWidth(), colors = OutlinedTextFieldDefaults.colors( focusedTextColor = PaleBlack, unfocusedTextColor = PaleBlack, focusedBorderColor = PalePink, unfocusedBorderColor = MediumGray.copy(alpha = 0.6f), focusedLabelColor = PalePink, unfocusedLabelColor = MediumGray, cursorColor = PaleBlack, focusedPlaceholderColor = MediumGray, unfocusedPlaceholderColor = MediumGray ) )
Spacer(modifier = Modifier.height(10.dp))
Button( onClick = { if (password != confirmPassword) { viewModel.showAuthError("Passwords do not match") } else { viewModel.register(fullName, email, password) } }, shape = RoundedCornerShape(25f), modifier = Modifier.fillMaxWidth(), colors = ButtonDefaults.buttonColors( containerColor = Color(0xFF2B2B2B), contentColor = Color(0xFFF6C9CB) ), ) { Label("REGISTER") }
if (viewModel.registerState is RegisterState.Success) { LaunchedEffect(Unit) { navController.navigate(Routes.LANGUAGE) { popUpTo("Register") { inclusive = true } } } } } }

